package brasfoot;
import java.nio.file.*;import java.util.*;import javax.swing.*;import java.awt.*;import javax.imageio.ImageIO;
public final class NativeAgendaCompetitionFilterWindowTest{
 private static Map<String,Object> row(String key,String date,long time,int division){Map<String,Object> row=new LinkedHashMap<String,Object>();row.put("competitionKey",key);row.put("competition","Liga");row.put("competitionCountryName","Brasil");row.put("competitionDivision",division);row.put("competitionType",1);row.put("date",date);row.put("dateMillis",time);row.put("home","Clube A");row.put("away","Clube B");row.put("result","x");return row;}
 private static JTable grid(JPanel panel){return (JTable)((JScrollPane)panel.getComponent(0)).getViewport().getView();}
 private static JComboBox<?> combo(JPanel panel){return (JComboBox<?>)((JPanel)panel.getComponent(1)).getComponent(1);}
 private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);java.util.List<Object> rows=new ArrayList<Object>();rows.add(row("id:2","03/01/2022",3,1));rows.add(row("id:1","02/01/2022",2,0));rows.add(row("id:1","01/01/2022",1,0));JFrame[] frame={null};JComboBox<?>[] filter={null};SwingUtilities.invokeAndWait(()->{JPanel first=NativeCareerDialogs.agendaPanel(rows),second=NativeCareerDialogs.agendaPanel(rows);Map<String,Object> regional=row("id:3","01/01/2022",1,34);regional.put("competitionType",3);JPanel regionalPanel=NativeCareerDialogs.agendaPanel(java.util.Collections.<Object>singletonList(regional));check(!combo(regionalPanel).getItemAt(1).toString().contains("Divis"),"Regional competition code was labeled as a national division");JTable firstGrid=grid(first),secondGrid=grid(second);JComboBox<?> countries=combo(first);filter[0]=countries;check(countries.getItemCount()==3,"Same-name competitions must remain separate options by ID");countries.setSelectedIndex(2);check(firstGrid.getRowCount()==2&&"01/01/2022".equals(firstGrid.getValueAt(0,0))&&"02/01/2022".equals(firstGrid.getValueAt(1,0)),"Competition filter must select matching ID and keep chronological order");check(secondGrid.getRowCount()==3&&combo(second).getSelectedIndex()==0,"Filtering one window changed another window");countries.setSelectedIndex(1);check(firstGrid.getRowCount()==1&&"03/01/2022".equals(firstGrid.getValueAt(0,0)),"Same competition name was incorrectly merged");countries.setSelectedIndex(0);check(firstGrid.getRowCount()==3&&rows.size()==3,"Show all must restore complete query without mutating source rows");countries.setSelectedIndex(2);JFrame owner=new JFrame("Agenda filtrada por competicao");frame[0]=owner;owner.add(first);owner.setSize(1000,480);owner.setLocationRelativeTo(null);owner.setVisible(true);});new Robot().waitForIdle();Thread.sleep(300);SwingUtilities.invokeAndWait(()->filter[0].showPopup());Thread.sleep(100);try{Path evidence=root.resolve("build/evidence-agenda-filter");Files.createDirectories(evidence);ImageIO.write(new Robot().createScreenCapture(frame[0].getBounds()),"png",evidence.resolve("filter.png").toFile());}finally{SwingUtilities.invokeAndWait(()->frame[0].dispose());}System.out.println("PASS real Agenda filters same-name competitions by ID, preserves chronology, source rows and independent window selection");}
}
